//! Boundaries for checked cleaned evidence, statistical scores, and complete output.
use super::entity_ingestion::EntitySearchPipelineError;
use crate::domain::models::{
    declaration_resolution::{ResolutionInput, ResolvedDeclarations, ScoredPairs, ScoringInput},
    entity_ingestion::EntityIngestionError,
};

/// Storage for one immutable declaration resolution run.
pub trait DeclarationResolutionStorage: Clone + Send + Sync + 'static {
    /// Reads and checks the cleaned observation and funding tables together.
    fn read_resolution_input(
        &self,
    ) -> impl Future<Output = Result<ResolutionInput, EntityIngestionError>> + Send;
    /// Publishes every completed output together without replacement.
    fn publish_resolution(
        &self,
        result: &ResolvedDeclarations,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Namespace for local provisional identities.
    fn resolution_run_key(&self) -> String;
}
/// Statistical scoring port. The implementation must report its actual model/runtime.
pub trait FunderScorer: Send + Sync {
    /// Scores bounded candidate profile pairs without assigning identities.
    fn score(
        &self,
        input: &ScoringInput,
    ) -> impl Future<Output = Result<ScoredPairs, EntityIngestionError>> + Send;
}
//! Coordinates checked evidence, statistical scoring, Rust policy, and publication.
use crate::domain::{
    models::{
        declaration_resolution::{DeclarationResolutionSummary, ResolvedDeclarations},
        entity_ingestion::EntityIngestionError,
    },
    repositories::declaration_resolution::{DeclarationResolutionStorage, FunderScorer},
};

/// Offline resolver with an explicitly configured statistical scorer.
pub struct DeclarationResolverService<S, F> {
    storage: S,
    scorer: F,
    candidate_budget: usize,
}
impl<S: DeclarationResolutionStorage, F: FunderScorer> DeclarationResolverService<S, F> {
    /// Supplies storage, scorer and the maximum candidate count.
    #[must_use]
    pub const fn new(storage: S, scorer: F, candidate_budget: usize) -> Self {
        Self {
            storage,
            scorer,
            candidate_budget,
        }
    }
    /// Resolves and publishes one ingestion run.
    ///
    /// # Errors
    /// Fails on incoherent evidence, scorer errors, budget refusal, or publication errors.
    pub async fn resolve_declarations(
        &self,
    ) -> Result<DeclarationResolutionSummary, EntityIngestionError> {
        let input = self.storage.read_resolution_input().await?;
        let scoring = input.scoring_input(self.candidate_budget);
        let scored = self.scorer.score(&scoring).await?;
        let result = ResolvedDeclarations::from_scored(
            &input,
            &scoring,
            scored,
            &self.storage.resolution_run_key(),
        )?;
        self.storage.publish_resolution(&result).await?;
        Ok(result.summary())
    }
}
//! Config for CLI

use anyhow::Context;
use std::{fs::read_to_string, io::Error as IoError, path::PathBuf};
use thiserror::Error;

use serde::{Deserialize, Serialize};

/// Environment configuration for data commands that use the database.
pub struct DataConfig {
    /// PostgreSQL connection string.
    pub connection_string: String,
}

impl DataConfig {
    /// Reads the database connection string from the environment.
    ///
    /// # Errors
    /// Returns an error if `DATABASE_URL` is missing or contains non-Unicode data.
    pub fn from_env() -> anyhow::Result<Self> {
        Ok(Self {
            connection_string: std::env::var("DATABASE_URL").context("DATABASE_URL must be set")?,
        })
    }
}

/// Configuration for capturing declarations for the stored member cohort.
#[derive(Serialize, Deserialize)]
pub struct DeclarationFetcherConfig {
    /// Root directory for ingestion datasets.
    pub data_dir: PathBuf,
    /// Nonzero API page size; validated when constructing the HTTP adapter.
    pub batch_size: u8,
}

impl TryFrom<&PathBuf> for DeclarationFetcherConfig {
    type Error = CliConfigError;

    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        Ok(rust_yaml::from_str(&raw)?)
    }
}

#[derive(Serialize, Deserialize)]
/// Config for the exposed application
pub struct FetcherConfig {
    /// Size of API batches
    pub batch_size: u8,
    /// Data store key
    pub data_dir: PathBuf,
}

impl TryFrom<&PathBuf> for FetcherConfig {
    type Error = CliConfigError;
    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        let config = rust_yaml::from_str(&raw)?;
        Ok(config)
    }
}

#[derive(Serialize, Deserialize)]
/// Config for the exposed application
pub struct LoaderConfig {
    /// Data store key
    pub data_dir: PathBuf,
}

impl TryFrom<&PathBuf> for LoaderConfig {
    type Error = CliConfigError;
    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        let config = rust_yaml::from_str(&raw)?;
        Ok(config)
    }
}

#[derive(Error, Debug)]
/// Collection of errors when parsing configuration
pub enum CliConfigError {
    #[error("yaml malformatted")]
    /// Yaml cannot be parsed
    FormattingError(#[from] rust_yaml::Error),
    #[error("unable to read config")]
    /// Config path invalid
    FileNotFound(#[from] IoError),
}

/// Runtime configuration for offline statistical declaration resolution.
#[derive(Deserialize)]
pub struct DeclarationResolverConfig {
    /// Root directory containing the existing ingestion run.
    pub data_dir: PathBuf,
    /// Python executable in the separately installed resolution environment.
    pub resolution_python: PathBuf,
    /// Worker path, relative to the invocation directory when not absolute.
    #[serde(default = "default_resolution_worker")]
    pub resolution_worker: PathBuf,
    /// Maximum profile candidates and expanded observation pairs.
    #[serde(default = "default_candidate_budget")]
    pub candidate_budget: usize,
}
fn default_resolution_worker() -> PathBuf {
    PathBuf::from("resolution/worker.py")
}
const fn default_candidate_budget() -> usize {
    1_000_000
}
impl TryFrom<&PathBuf> for DeclarationResolverConfig {
    type Error = anyhow::Error;
    fn try_from(path: &PathBuf) -> Result<Self, Self::Error> {
        let config: Self = rust_yaml::from_str(&read_to_string(path)?)?;
        anyhow::ensure!(
            config.candidate_budget > 0,
            "candidate_budget must be positive"
        );
        anyhow::ensure!(
            !config.resolution_python.as_os_str().is_empty(),
            "resolution_python must be configured"
        );
        Ok(config)
    }
}
